export function createTiles(){


	var groundTiles, surfaceTiles, surfaceTiles_v2, floodTiles, countMap;
	
	var mapData, elevationMap, floodData, surfaceMap;

	var cluster, dataa, dataa1;

	var maxElevation, minElevation;

	var tileSize = 100;
	var numberOfTiles = 5625;
	var numberOfTiles_X = Math.pow(numberOfTiles, 0.5)
	var side_length = numberOfTiles_X * tileSize;
	var elevationGround = 100;

	var pos_of_objects = [];

	mapData = mapDataManual();
	elevationMap = elevationMapManual();
	floodData = floodManual();
	surfaceMap = surfaceManual();

	maxElevation = findMaximum(elevationMap);
	minElevation = findMinimum(elevationMap);

	console.log(minElevation, maxElevation);

	groundTiles = [];
	surfaceTiles = [];
	surfaceTiles_v2 = [];
	floodTiles = [];

	countMap = {};

	// Ground Tiles
	countMap["water"] = 50;
	countMap["building"] = 50;
	countMap["road"] = 50;
	countMap["parks"] = 50;
	countMap["parking_lot"] = 50;


	// Surface Tiles v2
	countMap["road_v"] = 100;
	countMap["road_h"] = 100;
	countMap["road_c"] = 5;
	countMap["tree"] = 100;
	countMap["parking"] = 20;
	countMap["flood"] = 5000;

	// Surface Tiles
	countMap["Res1"] = 50;
	countMap["Res2"] = 50;
	countMap["Res3"] = 50;
	countMap["Pol"] = 1;
	countMap["Fire"] = 1;
	countMap["Hos"] = 1;
	countMap["School"] = 1;
	countMap["Wat"] = 1;
	countMap["Ind"] = 1;
	countMap["Com"] = 1;

	// Delete
	countMap["g1"] = 50;
	countMap["w1"] = 50;
	countMap["c1"] = 50;
	countMap["f1"] = 50;
	countMap["p1"] = 50;
	countMap["road1"] = 50;
	countMap["road2"] = 50;
	countMap["r1"] = 50;
	countMap["y1"] = 50;
	countMap["t1"] = 10050;

	


	for (var row = 0; row < 100; row++){
		groundTiles.push([]);
		surfaceTiles.push([]);
		floodTiles.push([]);
		surfaceTiles_v2.push([]);
		for (var column = 0; column < 100; column++){
			groundTiles[row].push(0);
			surfaceTiles[row].push(0);
			surfaceTiles_v2[row].push(0);
			floodTiles[row].push(0);
		};
	};

	/*
	readTextFile("../groundTiles.json", function(text){
    	dataa = JSON.parse(text);
    	dataa1 = dataa;
    	console.log(dataa1)
	});
	*/
	groundTiles = readGroundTiles();
	surfaceTiles = readSurfaceTiles();
	surfaceTiles_v2 = readSurfaceTiles_v2();
	floodTiles = readFloodTiles();
	for (var row = 0; row < 100; row++){
		for (var column = 0; column < 100; column++){
			countMap[groundTiles[row][column]["type"]]++;
			if (surfaceTiles[row][column] != 0){
				pos_of_objects.push([row, column]);
				countMap[surfaceTiles[row][column]["type"]]++;
			}

			if (surfaceTiles_v2[row][column] != 0){
				if (surfaceTiles_v2[row][column]["type"] == "tree"){countMap[surfaceTiles_v2[row][column]["type"]] += 10}
				else if (surfaceTiles_v2[row][column]["type"] == "road_h"){countMap[surfaceTiles_v2[row][column]["type"]] += 2}
				else if (surfaceTiles_v2[row][column]["type"] == "road_v"){countMap[surfaceTiles_v2[row][column]["type"]] += 2}
				else if (surfaceTiles_v2[row][column]["type"] == "road_c"){countMap[surfaceTiles_v2[row][column]["type"]] += 1}
				else if (surfaceTiles_v2[row][column]["type"] == "parking"){countMap[surfaceTiles_v2[row][column]["type"]] += 1}
				else {countMap[surfaceTiles_v2[row][column]["type"]] += 2};
				
			}
			if (floodTiles[row][column] != 0){
				countMap["flood"]++
			};

		}
	}

	


	return [groundTiles, surfaceTiles, surfaceTiles_v2, floodTiles, pos_of_objects, countMap, floodData, minElevation, maxElevation];

};


function getRandomArbitrary(min=80, max=120) {
	return Math.random() * (max - min) + min;
};


function groundTile (row, column, elevation, type, instanceId){
	this.row  = row;
	this.column = column;
	this.elevation = elevation;
	this.type = type;
	this.instanceId = instanceId;
	this.elevateStructure = 0;
	this.sandbag = 0;
	this.floodWall = 0;
	this.floodInsurance = false;
};

function surfaceTile(row, column, size, height, elevation, type, instanceId, peopleOnIt=50){
	this.row  = row;
	this.column = column;
	this.elevation = elevation;
	this.type = type;
	this.instanceId = instanceId;
	this.height = height;
	this.size = size;
	this.floodInsurance = false;
	this.peopleOnIt = peopleOnIt;
};


function floodTile(type, row, column, height, elevation, size, instanceId){
	this.type = type;
	this.row  = row;
	this.column = column;
	this.elevation = elevation;
	this.instanceId = instanceId;
	this.height = height;
	this.size = size;
};

